_CORE = '"./three.core.min.js";'
def _names(s): return [x.strip().partition(' as ') for x in s.split(',') if x.strip()]

def _exports(src):
    "The code before the last `export{...}` of a module, and the names that it exports as `(local, _, name)`."
    m = re.search(r'export\{([^}]*)\};?\s*$', src)
    if not m: raise ValueError('the module does not end with an export')
    return src[:m.start()], _names(m[1])

@functools.cache
def three_js() -> str:
    "three.js as one classic script that sets `window.RupakaTHREE`, made from the two vendored module files."
    d = VENDOR/'three'
    core, cx = _exports((d/'three.core.min.js').read_text())
    mod, mx = _exports((d/'three.module.min.js').read_text())
    imp, rex = (re.search(r'%s\{([^}]*)\}from%s' % (k, re.escape(_CORE)), mod) for k in ('import', 'export'))
    if not (imp and rex) or re.search(r'\bimport\s*[{(*]', mod[imp.end():]):
        raise ValueError('three.module.min.js has another import; check the vendored files')
    obj = lambda ns, f: '{' + ','.join(f(a, b or a) for a, _, b in ns) + '}'
    core += 'return' + obj(cx, lambda a, b: f'{b}:{a}') + ';'
    body = ('const' + obj(_names(imp[1]), lambda a, b: f'{a}:{b}') + '=__core;' + mod[imp.end():rex.start()] + mod[rex.end():]
            + 'return{' + ','.join(f'{a}:__core.{a}' for a, _, _ in _names(rex[1])) + ',' + obj(mx, lambda a, b: f'{b}:{a}')[1:] + ';')
    return ('/* three.js %s, MIT licence: rupaka/static/vendor/three/LICENSE */\n(()=>{"use strict";if(window.RupakaTHREE)return;'
            'const __core=(()=>{%s})();window.RupakaTHREE=(()=>{%s})();})();' % (THREE.version, core, body))

